constexpr uint32_t calculateChecksum(const uint8_t* data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
        checksum = (checksum & 0xFFFF) + (checksum >> 16);
    }
    return ~checksum & 0xFFFF;
